  NetworkPlus.prototype._rebuild = function () {
    if (this._root && this._root.parentNode) {
      this._root.parentNode.removeChild(this._root)
    }
    this._selected = null
    this._initDom()
    if (this._visible) {
      this.show()
    }
  }

